import sys, json, random
sys.path.insert(0, '/workspace/tmp/t')
from harness import *

def naive(frames, reject, limit, is_crypto):
    """frames: list of (offset, bytes). Returns (None, highest, prefixhex) or (idx, code, None)."""
    data = {}
    highest = 0
    for i, (off, b) in enumerate(frames):
        end = off + len(b)
        if end > limit:
            return (i, 'CRYPTO_BUFFER_EXCEEDED' if is_crypto else 'FLOW_CONTROL_ERROR', None)
        for k in range(len(b)):
            o = off + k
            if o in data and data[o] != b[k] and reject:
                return (i, 'PROTOCOL_VIOLATION', None)
        for k in range(len(b)):
            o = off + k
            if o not in data:
                data[o] = b[k]
        highest = max(highest, end)
    p = 0
    while p in data:
        p += 1
    return (None, highest, bytes(data[i] for i in range(p)).hex())

random.seed(99)
fails = 0
trials = 0
for trial in range(300):
    overlap = random.choice(['reject', 'first'])
    reject = overlap == 'reject'
    lim = random.choice([4, 8, 16, 32, 65536])
    is_crypto = random.choice([True, False])
    nframes = random.randint(1, 10)
    frames = []
    for i in range(nframes):
        off = random.randint(0, 24)
        ln = random.randint(0, 8)
        b = bytes(random.randrange(4) for _ in range(ln))   # small alphabet -> many overlaps
        frames.append((off, b))
    spec_frames = [CR(o, b.hex()) if is_crypto else ST(0, o, b.hex()) for o, b in frames]
    exp = naive(frames, reject, lim, is_crypto)
    trials += 1

    # (a) all frames in one packet: error -> full rollback (empty state)
    if is_crypto:
        evs = [dg(1, [pk("I", 0, spec_frames)])]
    else:
        evs = [key(0, "A", "install"), dg(1, [pk("A", 0, spec_frames)])]
    got, _ = run(d1(evs, overlap=overlap, crypto_limit=lim, max_stream_data=lim))
    r = got['results'][0]
    p0 = r['packets'][-1]
    c = r['crypto'][0] if is_crypto else None
    st = r['streams'][0] if r['streams'] else None
    if exp[0] is None:
        ok = p0['status'] == 'accepted'
        if is_crypto:
            ok = ok and (c['highest'], c['contiguous_hex']) == (exp[1], exp[2])
        else:
            ok = ok and st is not None and (st['highest'], st['delivered_hex']) == (exp[1], exp[2])
            ok = ok and r['total'] == exp[1]
    else:
        ok = (p0['status'], p0['reason'], p0['frame']) == ('error', exp[1], exp[0])
        ok = ok and r['streams'] == [] and r['total'] == 0
        ok = ok and all(x['highest'] == 0 and x['contiguous_hex'] == '' for x in r['crypto'])
        ok = ok and r['conn' if False else 'connection' if False else 'conn'][0] == 'closed'
    if not ok:
        fails += 1
        print('FAIL(a)', trial, overlap, lim, is_crypto, [(o, b.hex()) for o, b in frames], exp)
        print('  ', json.dumps(r)[:600])

    # (b) one frame per packet, only when no error expected
    if exp[0] is None and nframes > 1:
        trials += 1
        if is_crypto:
            evs = [dg(i + 1, [pk("I", i, [f])]) for i, f in enumerate(spec_frames)]
        else:
            evs = [key(0, "A", "install")] + [dg(i + 1, [pk("A", i, [f])]) for i, f in enumerate(spec_frames)]
        got, _ = run(d1(evs, overlap=overlap, crypto_limit=lim, max_stream_data=lim))
        r = got['results'][0]
        st = r['streams'][0] if r['streams'] else None
        c = r['crypto'][0] if is_crypto else None
        ok = all(p['status'] == 'accepted' for p in r['packets'])
        if is_crypto:
            ok = ok and (c['highest'], c['contiguous_hex']) == (exp[1], exp[2])
        else:
            ok = ok and st is not None and (st['highest'], st['delivered_hex']) == (exp[1], exp[2])
            ok = ok and r['total'] == exp[1]
        if not ok:
            fails += 1
            print('FAIL(b)', trial, overlap, lim, is_crypto, [(o, b.hex()) for o, b in frames], exp)
            print('  ', json.dumps(r)[:600])
print('trials', trials, 'fails', fails)
